import {showLayerMenu} from './layer-menu.js';import {showGraph} from '../timeline/graph.js';
import {currentMesh} from '../scene/mesh-edit.js';
import {evaluated} from '../animation/evaluate.js';
import {find,isLocked,selectionRoots,locate} from '../document/model.js';import {escape} from '../renderer/svg.js';import {shapeTools} from './shapes-menu.js';import {editorAction,editorInput} from './editor.js';import {showHelp} from './help.js';
const combineIcon=action=>{const a='<rect x="3" y="3" width="13" height="13"/>',b='<rect x="10" y="10" width="13" height="13"/>';return `<svg viewBox="0 0 26 26" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8">${action==='combine-union'?'<path fill="currentColor" d="M3 3H16V10H23V23H10V16H3Z"/>':action==='combine-intersect'?a+b+'<rect x="10" y="10" width="6" height="6" fill="currentColor"/>':action==='combine-subtract'?'<path fill="currentColor" d="M3 3H16V10H10V16H3Z"/>'+b:action==='combine-exclude'?'<path fill="currentColor" d="M3 3H16V10H10V16H3ZM16 10H23V23H10V16H16Z"/>':a+b}</svg>`;};
const button=(action,label,disabled=false)=>`<button data-edit="${action}" ${action.startsWith('combine-')?`class="combine-icon" title="${label}" aria-label="${label}"`:""} ${disabled?'disabled':''}>${action.startsWith('combine-')?combineIcon(action):''}<span>${label}</span></button>`;
export function renderContext(a){const el=document.querySelector('#context-bar'),n=find(a.doc,a.selected[0]),disabled=!n||isLocked(a.doc,n.id);let mode=a.tool==='mesh'?'Mesh shading':a.tool==='direct'?'Edit points':shapeTools.includes(a.tool)?'Drawing: '+({rect:'Rectangle',ellipse:'Ellipse',triangle:'Triangle',polygon:'Polygon',star:'Star',line:'Line'}[a.tool]):a.tool==='select'?'Select objects':a.tool==='path'?'Draw a path':a.tool==='pencil'?'Draw with Pencil':a.tool==='text'?'Add text':'Pan canvas',body='';
 if(a.selected.length>1){mode=a.selected.length+' selected';const roots=selectionRoots(a.doc,a.selected),same=roots.length>1&&roots.every(n=>!isLocked(a.doc,n.id)&&locate(a.doc,n.id).list===locate(a.doc,roots[0].id).list),canCombine=same&&roots.every(n=>['rectangle','ellipse'].includes(n.type)||['path','freehand'].includes(n.type)&&(n.closed||n.rawPath||n.nodes.some(p=>p.close))),canJoin=same&&roots.length===2&&roots.every(n=>['path','freehand'].includes(n.type)&&!n.rawPath&&n.nodes.length>=2&&!n.closed&&!n.nodes.some(p=>p.close));body=`<span class="context-label">Combine shapes</span>${button('combine-union','Unite',!canCombine)}${button('combine-subtract','Subtract front',!canCombine)}${button('combine-intersect','Keep overlap',!canCombine)}${button('combine-exclude','Exclude overlap',!canCombine)}${button('combine-compound','Compound path',!canCombine)}${button('join','Join paths',!canJoin)}<span class="context-note">${canCombine?'Combining uses the current frame. Undo restores the originals.':'Choose closed shapes in the same group to combine.'}</span>`;}
 else if(n&&a.tool==='mesh'&&n.mesh){const mesh=currentMesh(n,a.time),index=Math.min(a.activeMesh||0,mesh.points.length-1),p=mesh.points[index];mode=`Mesh · ${n.name} · point ${index+1}`;body=`${button('mesh-colour','Point colour',disabled)+button('mesh-key',n.tracks.mesh?.length?'◇ Add mesh key':'◇ Animate mesh',disabled)}${button('mesh-fit','Fit to shape',disabled)+button('mesh-split','Subdivide cell',disabled||mesh.rows>=17||mesh.cols>=17)}<button data-edit="mesh-tap" aria-pressed="${!!a.meshSplit}" ${mesh.rows>=17||mesh.cols>=17?'disabled':''} class="${a.meshSplit?'active':''}" ${disabled?'disabled':''}>Tap to subdivide</button>${button('mesh-row','More rows',disabled||mesh.rows>=17)}${button('mesh-col','More columns',disabled||mesh.cols>=17)}<span class="context-note">${mesh.rows} × ${mesh.cols} grid · hold a point for colour · maximum 17 × 17</span>`;}
 else if(n&&a.nodeEdit&&['path','freehand'].includes(n.type)&&!n.rawPath){mode=`Edit points · ${n.name}${Number.isInteger(a.activeNode)?' · point '+(a.activeNode+1):''}`;const pointDisabled=disabled||!Number.isInteger(a.activeNode);body=button('previous-point','‹ Point',disabled)+button('next-point','Point ›',disabled)+button('split','Add midpoint',pointDisabled)+button('smooth','Smooth point',pointDisabled)+button('corner','Corner point',pointDisabled)+button('delete-point','Delete point',pointDisabled)+button('toggle-close',n.closed||n.nodes.some(p=>p.close)?'Open path':'Close path',disabled)+button('reverse','Reverse path',disabled)+button('shape-key',n.tracks.nodes?.length?'◇ Add shape key':'◇ Animate points',disabled)+`<span class="context-note">${n.tracks.nodes?.length?'Point edits create keys at '+a.time.toFixed(2)+'s':'Enable Animate points, then change points at a later time.'}</span>`;}
 else if(n){if(n.type==='text')mode='Edit text';mode+=' · '+n.name;body=button('direct',n.type==='text'?'Edit text':n.type==='group'?'Direct select':'Edit points',disabled)+(n.type==='group'?button('contents','Select contents',disabled):n.type!=='text'?button('mesh','Mesh shading',disabled):'')+`<button data-add-key ${disabled?'disabled':''}>◇ Add keyframe</button>`;}
 else body='<span class="context-note">Choose Shapes → draw → Add keyframe. Drag empty canvas to select several.</span>';
 if(a.selected.length===1&&n&&n.type!=='group'&&n.type!=='text'&&a.tool!=='mesh'){if(n.fill!=='none')body+=`<label class="context-color">Fill<input type="color" aria-label="Shape fill colour" data-prop="fill" value="${evaluated(n,a.time).fill==='none'?a.drawColor:evaluated(n,a.time).fill}" ${disabled?'disabled':''}></label>`;if(n.fill==='none'||n.strokeWidth>0)body+=`<div class="line-dock"><label>Width<input data-prop="strokeWidth" aria-label="Line width" type="number" min="0" step="1" value="${evaluated(n,a.time).strokeWidth}" style="width:60px"></label><label>Style<select data-prop="lineStyle" aria-label="Line style">${['solid','dashed','dotted'].map(x=>' <option '+(x===(n.lineStyle||'solid')?'selected':'')+'>'+x+'</option>').join('')}</select></label><label>Profile<select data-prop="strokeProfile" aria-label="Line width profile">${[['uniform','Uniform'],['taper-both','Taper ends'],['taper-start','Thin to thick'],['taper-end','Thick to thin'],['brush','Brush']].map(([v,label])=>'<option value="'+v+'" '+(v===(n.strokeProfile||'uniform')?'selected':'')+'>'+label+'</option>').join('')}</select></label></div>`;}
 const active=document.activeElement;if(el.contains(active)&&active.matches('input,select'))return;el.innerHTML=`<div class="context-heading"><strong>${escape(mode)}</strong><div class="context-header-actions"><button data-layer-menu ${!n?'disabled':''}>Layer</button><button data-layer-graph ${!n?'disabled':''}>Graph</button><button data-context-help>How to animate</button><button class="context-properties" data-properties>Properties</button></div></div><div class="context-actions">${body}</div>`;
}
export function bindContext(a){const el=document.querySelector('#context-bar');el.addEventListener('click',e=>{const action=e.target.closest('[data-edit]')?.dataset.edit;if(action)return a.safe(()=>editorAction(a,action));if(e.target.closest('[data-add-key]'))document.querySelector('#add-key').click();if(e.target.closest('[data-layer-menu]'))return showLayerMenu(a);if(e.target.closest('[data-layer-graph]'))return showGraph(a);if(e.target.closest('[data-context-help]'))showHelp(a);if(e.target.closest('[data-properties]'))document.querySelector('.inspector').classList.add('open');});el.addEventListener('input',e=>a.properties.input(e));el.addEventListener('change',e=>{if(a.properties.pending)a.properties.flush();else a.properties.change(e);if(!e.target.matches('input[type=color]'))a.render();});}

